const $=s=>document.querySelector(s);
const state={user:null,classes:[],domains:[],events:[],scope:'school',month:new Date(new Date().getFullYear(),new Date().getMonth(),1),selected:dateKey(new Date()),auth:'login'};
function dateKey(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function elem(tag,cls,text){const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e}
async function api(path,data){
    if(data&&state.user?.role==='admin'){
        const privileged=path.startsWith('admin/')||['event/save','event/delete','comment/delete','comment/pin'].includes(path)||(path==='send-code'&&data.user_id);
        if(privileged)data={...data,admin_password:await reauth()};
    }
    const r=await fetch('/api/'+path,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json','X-SMC-Request':'1'}:{},body:data?JSON.stringify(data):undefined});
    const j=await r.json();if(!r.ok)throw Error(j.error||'요청에 실패했습니다.');return j;
}

function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').hidden=true,5000)}
function fillSelect(el,values,current){el.replaceChildren(...values.map(v=>{const o=elem('option','',v);o.value=v;return o}));if(current)el.value=current}
async function bootstrap(){const previousUser=state.user?.id;const previousClass=$('#classFilter').value;const b=await api('bootstrap');Object.assign(state,b);if(previousUser!==state.user?.id)clearDirectoryState();if(state.user&&previousUser!==state.user.id)state.scope='all';if(!state.user&&previousUser)state.scope='school';['#signupClass','#classFilter'].forEach(s=>fillSelect($(s),state.classes,state.user?.class_name));fillSelect($('#userClass'),[...state.classes,'관리자','교사']);if(previousUser===state.user?.id&&state.classes.includes(previousClass))$('#classFilter').value=previousClass;if(!state.classes.includes($('#classFilter').value))$('#classFilter').value=state.classes[0];$('#domainHint').textContent=state.domains.map(d=>'@'+d).join(' · ');$('#domains').value=state.domains.join(', ');renderAccount();if(state.user?.role!=='admin')showCalendar();await loadEvents()}
function renderAccount(){const box=$('#account');box.replaceChildren();if(state.user){box.append(elem('span','avatar',state.user.name.slice(0,1)),elem('span','',state.user.name+' · '+state.user.class_name));const b=elem('button','secondary desktopLogout','로그아웃');b.onclick=logoutAccount;const profile=elem('button','accountIcon','');profile.type='button';profile.setAttribute('aria-label','내 계정');profile.setAttribute('aria-haspopup','dialog');profile.title='내 계정';profile.onclick=openProfile;withActionIcon(profile,'user');withActionIcon(b,'logout');const inbox=notificationButton();inbox.onclick=openNotifications;box.append(inbox,profile,b)}else{const b=elem('button','secondary','로그인 / 회원가입');b.onclick=()=>openAuth('login');withActionIcon(b,'login');box.append(b)}$('#adminNav').hidden=state.user?.role!=='admin';const inquiryLabel=$('#inquiryNav span');if(inquiryLabel)inquiryLabel.textContent=state.user?.role==='admin'?'문의함':'관리자 문의';document.querySelectorAll('[data-inquiry-menu]').forEach(button=>{const text=button.querySelector('.quickInquiryLabel');if(text)text.textContent=state.user?.role==='admin'?'문의함':'관리자 문의'});document.querySelectorAll('[data-admin-menu]').forEach(button=>button.hidden=state.user?.role!=='admin');$('#addEvent').hidden=!!state.user&&!['admin','teacher'].includes(state.user.role)&&(state.scope==='school'||$('#classFilter').value!==state.user.class_name)}
async function setScope(scope){showCalendar();state.scope=scope;await loadEvents()}
async function loadEvents(){try{
    const scope=state.scope;const className=$('#classFilter').value;
    const r=await api('events?scope='+(scope==='school'?'school':'class')+'&class='+encodeURIComponent(className));
    if(state.scope!==scope||$('#classFilter').value!==className)return;
    state.events=scope==='class'?r.events.filter(event=>event.scope==='class'):r.events;
    $('#viewLabel').textContent=scopeLabel();$('#classFilter').hidden=scope==='school';
    for(const [id,value] of [['#allTab','all'],['#schoolTab','school'],['#classTab','class']])$(id).classList.toggle('selected',scope===value);
    $('#allNav').classList.toggle('active',scope==='all');$('#schoolNav').classList.toggle('active',scope==='school');$('#classNav').classList.toggle('active',scope==='class');
    renderAccount();renderCalendar();
}catch(e){toast(e.message)}}
function scopeLabel(){return {all:'전체 일정',school:'학사일정',class:'학급일정'}[state.scope]}

function renderCalendar(){const y=state.month.getFullYear(),m=state.month.getMonth();$('#yearLabel').textContent=y;$('#monthLabel').textContent=(m+1)+'월';const start=new Date(y,m,1);start.setDate(1-start.getDay());const grid=$('#calendar');grid.replaceChildren();const days=Math.ceil((new Date(y,m,1).getDay()+new Date(y,m+1,0).getDate())/7)*7;for(let i=0;i<days;i++){const d=new Date(start);d.setDate(start.getDate()+i);const key=dateKey(d);const b=elem('button','day'+(d.getMonth()!==m?' outside':'')+(key===state.selected?' chosen':'')+(key===dateKey(new Date())?' isToday':''));b.setAttribute('aria-label',key+' 일정 보기');b.setAttribute('aria-pressed',key===state.selected);b.append(elem('span','dateNumber',d.getDate()));const events=state.events.filter(e=>e.date===key);events.slice(0,2).forEach(e=>{const chip=elem('span','eventChip '+e.scope,e.title);chip.onclick=event=>{event.stopPropagation();state.selected=key;openComments(e)};b.append(chip)});if(events.length>2)b.append(elem('span','more','+'+(events.length-2)+'개 더보기'));b.onclick=()=>{state.selected=key;if(state.detail&&innerWidth<=650)mobileMiniExpanded=false;renderCalendar();scrollToScheduleDetails()};grid.append(b)}$('#monthCount').textContent='이번 달 '+state.events.filter(e=>e.date.startsWith(`${y}-${String(m+1).padStart(2,'0')}`)).length+'개의 일정';renderAgenda()}
function renderAgenda(){closeActionMenu();const d=new Date(state.selected+'T12:00:00');$('#selectedDate').textContent=(d.getMonth()+1)+'월 '+d.getDate()+'일';$('#selectedWeekday').textContent=d.toLocaleDateString('ko-KR',{weekday:'long'})+(state.selected===dateKey(new Date())?' · 오늘':'');const box=$('#agendaList');box.replaceChildren();const list=state.events.filter(e=>e.date===state.selected);if(!list.length){const empty=elem('div','empty');empty.append(elem('div','emptyIcon','▦'),elem('div','','등록된 일정이 없어요.'),elem('div','','새로운 일정이 생기면 여기에서 확인하세요.'));box.append(empty)}list.forEach(e=>{const item=elem('article','agendaEvent');item.append(elem('span','tag '+e.scope,e.scope==='school'?'학교 전체':e.class_name),elem('h3','',e.title),elem('p','',e.description||'상세 내용이 없습니다.'));if(state.user&&(['admin','teacher'].includes(state.user.role)||e.author===state.user.id&&e.class_name===state.user.class_name)){bindActionMenu(item,'event-'+e.id,[{label:'일정 수정',run:()=>openEvent(e)},{label:'일정 삭제',danger:true,run:async()=>{if(!confirm('이 일정을 삭제하시겠어요?'))return;await api('event/delete',{id:e.id,scope:e.scope,class_name:e.class_name});await loadEvents()}}]);}item.tabIndex=0;item.setAttribute('aria-label',e.title+' · 일정과 댓글 보기');item.classList.toggle('selectedEvent',state.selectedEvent===e.id);item.onclick=event=>{if(!event.target.closest('button'))openComments(e)};item.onkeydown=event=>{if(event.target===item&&(event.key==='Enter'||event.key===' ')){event.preventDefault();openComments(e)}};const featured=e.featured_comment;if(featured){const quote=elem('div','featuredComment'+(featured.pinned?' isPinned':' isBest'));quote.append(elem('strong','',featured.pinned?'고정 댓글':'베스트 댓글 · 좋아요 '+featured.likes),elem('p','','댓글 — '+featured.body));item.append(quote);}box.append(item)});syncDetailSelection(list)}
function openAuth(mode){state.auth=mode;$('#authForm').reset();$('#authForm').elements.email.setCustomValidity('');$('#authMessage').textContent='';$('#registerFields').hidden=mode!=='register';$('#authTitle').textContent=mode==='login'?'다시 만나 반가워요.':'우리 학교의 하루에 함께해요.';$('#authSubmit').textContent=mode==='login'?'로그인':'인증 완료하고 가입하기';$('#loginTab').classList.toggle('selected',mode==='login');$('#registerTab').classList.toggle('selected',mode==='register');for(const name of ['code','name','email','class_name','password_confirm'])$('#authForm').elements[name].required=mode==='register';$('#passwordHint').hidden=mode!=='register';$('#passwordConfirmLabel').hidden=mode!=='register';$('#authForm').elements.password.minLength=mode==='register'?8:1;$('#authForm').elements.password.autocomplete=mode==='register'?'new-password':'current-password';updateMemberType();resetSignupValidation();if(!$('#authDialog').open)$('#authDialog').showModal()}
function formObject(form){return Object.fromEntries(new FormData(form))}
async function submit(form,message,fn){const buttons=form.querySelectorAll('button');buttons.forEach(b=>b.disabled=true);$(message).textContent='';try{await fn(formObject(form))}catch(e){if(e.message!=='취소')$(message).textContent=e.message}finally{buttons.forEach(b=>b.disabled=false)}}
$('#authForm').onsubmit=e=>{e.preventDefault();submit(e.target,'#authMessage',async b=>{if(state.auth==='register'){if(b.password!==b.password_confirm)throw Error('비밀번호 확인이 일치하지 않습니다.');if(b.member_type==='teacher')throw Error('교사 계정은 관리자에게 문의해 주세요.');if(!checkSignupEmail())return;}await api(state.auth==='login'?'login':'register',b);if(state.auth==='register'){openAuth('login');$('#authMessage').textContent='가입이 완료되었습니다. 로그인해 주세요.';return}$('#authDialog').close();await bootstrap();await setScope('all');toast('로그인했습니다.')})};
$('#sendCode').onclick=async()=>{const b=$('#sendCode');if(!checkSignupEmail()||!$('#authForm').elements.email.reportValidity())return;b.disabled=true;$('#authMessage').textContent='전송 중입니다…';try{await api('send-code',{email:$('#authForm').elements.email.value});$('#authMessage').textContent='인증 코드를 전송했습니다. 메일함을 확인해 주세요.'}catch(e){$('#authMessage').textContent=e.message}finally{b.disabled=false}};
function openEvent(event){if(!state.user){openAuth('login');toast('일정을 등록하려면 로그인해 주세요.');return}const f=$('#eventForm');f.reset();$('#eventMessage').textContent='';$('#eventHeading').textContent=event?'일정 수정':'일정 등록';const defaults=event||{date:state.selected,scope:state.scope==='school'?'school':'class',class_name:state.classes.includes(state.user.class_name)?state.user.class_name:$('#classFilter').value};Object.entries(defaults).forEach(([k,v])=>{if(f.elements[k])f.elements[k].value=v??''});const admin=state.user.role==='admin';const staff=['admin','teacher'].includes(state.user.role);$('#eventScope').disabled=!staff;fillSelect($('#eventClass'),state.classes,defaults.class_name);$('#eventClassLabel').hidden=!staff||f.elements.scope.value==='school';$('#eventDialog').showModal()}
$('#eventForm').onsubmit=e=>{e.preventDefault();submit(e.target,'#eventMessage',async b=>{if(!['admin','teacher'].includes(state.user.role)){b.scope='class';b.class_name=state.user.class_name}await api('event/save',b);$('#eventDialog').close();await loadEvents();toast('일정을 저장했습니다.')})};
function reauth(){return new Promise((resolve,reject)=>{const d=$('#reauthDialog'),f=$('#reauthForm');f.reset();$('#reauthAction').textContent='계속하려면 비밀번호를 입력하세요.';let done=false;f.onsubmit=e=>{e.preventDefault();done=true;const p=f.elements.password.value;f.reset();d.close();resolve(p)};d.onclose=()=>{f.reset();if(!done)reject(Error('취소'))};d.showModal()})}
