$('#adminNav').onclick=()=>{closeMobileQuickMenu();$('#mealPage').hidden=true;$('#mealNav').classList.remove('active');if(state.user?.role!=='admin')return;$('#userList').replaceChildren();['#allNav','#schoolNav','#classNav'].forEach(id=>$(id).classList.remove('active'));$('.workspace').hidden=true;$('.toolbar').hidden=true;$('#adminPage').hidden=false;$('#viewLabel').textContent='관리자';$('#adminNav').classList.add('active');selectAdminPane('inquiries',true);};
