$('#inquiryNav').onclick=()=>{if(state.user?.role==='admin'){$('#adminNav').click();return}if(!state.user){openAuth('login');toast('문의하려면 로그인해 주세요.');return}$('#inquiryForm').reset();$('#inquiryMessage').textContent='';$('#inquiryDialog').showModal()};
