function showCalendar(){$('#mealPage').hidden=true;$('#mealNav').classList.remove('active');$('.workspace').hidden=false;$('.toolbar').hidden=false;$('#adminPage').hidden=true;$('#adminNav').classList.remove('active');$('#viewLabel').textContent=scopeLabel();for(const [id,scope] of [['#allNav','all'],['#schoolNav','school'],['#classNav','class']])$(id).classList.toggle('active',state.scope===scope);}
