function checkSignupEmail(){const input=$('#authForm').elements.email;const email=input.value.trim().toLowerCase();const valid=email.includes('@')&&state.domains.includes(email.split('@').pop());input.setCustomValidity(valid?'':'허용된 학교 이메일 도메인이 아닙니다.');if(!valid){$('#authMessage').textContent='허용된 학교 이메일 도메인이 아닙니다.';input.reportValidity();}return valid;}
$('#authForm').elements.email.addEventListener('input',()=>$('#authForm').elements.email.setCustomValidity(''));
$('#authForm').elements.email.addEventListener('blur',()=>{if(state.auth==='register'&&$('#authForm').elements.email.value)checkSignupEmail();});
// 입력, 팝업 재표시, 화면 폭 변경 시 텍스트 영역 높이를 조정합니다.
function fitTextarea(field){
    if(!field.getClientRects().length)return;
    const style=getComputedStyle(field);
    const lineHeight=parseFloat(style.lineHeight)||parseFloat(style.fontSize)*1.7;
    const padding=parseFloat(style.paddingTop)+parseFloat(style.paddingBottom);
    const border=parseFloat(style.borderTopWidth)+parseFloat(style.borderBottomWidth);
    const minimum=Math.min(260,field.rows*lineHeight+padding+border);
    field.style.height='auto';
    field.style.height=Math.min(260,Math.max(minimum,field.scrollHeight+border))+'px';
}
function fitAllTextareas(){document.querySelectorAll('textarea').forEach(fitTextarea)}
document.querySelectorAll('textarea').forEach(field=>field.addEventListener('input',()=>fitTextarea(field)));
document.querySelectorAll('form').forEach(form=>form.addEventListener('reset',()=>requestAnimationFrame(fitAllTextareas)));
const textareaWidths=new WeakMap();
const textareaObserver=new ResizeObserver(entries=>{for(const entry of entries){const width=entry.contentRect.width;if(textareaWidths.get(entry.target)!==width){textareaWidths.set(entry.target,width);fitTextarea(entry.target)}}});
document.querySelectorAll('textarea').forEach(field=>textareaObserver.observe(field));
const dialogObserver=new MutationObserver(()=>requestAnimationFrame(fitAllTextareas));
document.querySelectorAll('dialog').forEach(dialog=>dialogObserver.observe(dialog,{attributes:true,attributeFilter:['open']}));
requestAnimationFrame(fitAllTextareas);

