async function openNotifications(){try{const result=await api('notifications');const list=$('#notificationList');list.replaceChildren();if(!result.notifications.length)list.append(elem('p','muted','아직 알림이 없습니다.'));for(const n of result.notifications){const item=elem('article','messageCard'+(n.is_read?'':' unread'));item.append(elem('h3','',n.title),elem('small','',new Date(n.created).toLocaleString('ko-KR')),elem('p','',n.body));if(!n.is_read){const b=elem('button','secondary','읽음 표시');b.onclick=async()=>{await api('notifications/read',{id:n.id});await bootstrap();await openNotifications()};item.append(b)}list.append(item)}if(!$('#notificationsDialog').open)$('#notificationsDialog').showModal()}catch(e){toast(e.message)}}
