$('#noticeForm').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('.primary');button.disabled=true;$('#noticeResult').textContent='';try{if(!state.capabilities?.includes('bulk_notifications_v2'))throw Error('새 알림 기능을 사용하려면 서버를 재시작한 뒤 새로고침하세요.');const all=$('#noticeMode').value==='all';if(!all&&!selectedRecipients.size)throw Error('수신자를 한 명 이상 선택하세요.');if(!confirm(all?'전체 회원에게 알림과 이메일을 보낼까요?':'선택한 '+selectedRecipients.size+'명에게 알림과 이메일을 보낼까요?'))return;const data=formObject(e.target);if(!all)data.user_ids=[...selectedRecipients.keys()];const result=await api('admin/notice',data);e.target.elements.title.value='';e.target.elements.body.value='';$('#noticeResult').textContent=notificationResult(result)+(result.failures?.length?'\n'+result.failures.map(f=>f.email+': '+f.reason).join('\n'):'');toast(notificationResult(result))}catch(error){if(error.message!=='취소')$('#noticeResult').textContent=error.message}finally{button.disabled=false}};
