function openComments(event){state.detail=true;state.selectedEvent=event.id;setDetailLayout(true);renderCalendar();scrollToScheduleDetails();}
function setDetailLayout(detail){$('.workspace').classList.toggle('detailMode',detail);$('#commentsPanel').hidden=!detail;$('#expandCalendar').hidden=!detail;syncMobileMini(detail);updateMiniCalendar(detail);}
function syncDetailSelection(events){if(!state.detail)return;setDetailLayout(true);const selected=events.find(e=>e.id===state.selectedEvent)||events[0];if(!selected){state.selectedEvent=null;$('#commentsTitle').textContent='선택한 날짜에 일정이 없습니다.';$('#commentsList').replaceChildren();$('#commentForm').hidden=true;return}state.selectedEvent=selected.id;document.querySelectorAll('.agendaEvent').forEach((item,i)=>item.classList.toggle('selectedEvent',events[i]?.id===selected.id));if($('#commentForm').elements.event_id.value!==String(selected.id)){$('#commentForm').elements.body.value='';fitTextarea($('#commentForm').elements.body);}$('#commentForm').elements.event_id.value=selected.id;$('#commentsTitle').textContent=selected.title+' · '+selected.date;$('#commentMessage').textContent='';$('#commentForm').hidden=!state.user;if(state.user)loadComments(selected.id);else{const login=elem('button','secondary','로그인하고 댓글 보기');login.onclick=()=>openAuth('login');$('#commentsList').replaceChildren(elem('p','muted','댓글은 로그인 후 이용할 수 있습니다.'),login)}}
async function loadComments(eventId){const list=$('#commentsList');list.replaceChildren(elem('p','muted','댓글을 불러오는 중입니다.'));try{const result=await api('comments?event_id='+eventId);if(state.selectedEvent!==Number(eventId)||!state.detail)return;list.replaceChildren();if(!result.comments.length)list.append(elem('p','muted','첫 댓글을 작성해 보세요.'));for(const comment of result.comments){const item=elem('article','messageCard');if(comment.pinned)item.append(elem('div','tag','고정 댓글'));item.append(elem('strong','',comment.name||'삭제된 계정'),elem('small','', ' · '+new Date(comment.created).toLocaleString('ko-KR')+(comment.updated_at?' · 수정됨':'')),elem('p','',comment.body));const actions=elem('div','commentActions');const like=elem('button','secondary', '♡ '+comment.likes);like.setAttribute('aria-label','좋아요 '+comment.likes);like.setAttribute('aria-pressed',!!comment.liked);like.classList.toggle('liked',!!comment.liked);like.onclick=async()=>{like.disabled=true;try{await api('comment/like',{id:comment.id,liked:!comment.liked});await loadEvents()}catch(e){toast(e.message)}finally{like.disabled=false}};actions.append(like);if(state.user&&['admin','teacher'].includes(state.user.role)){const pin=elem('button','secondary',comment.pinned?'고정 해제':'고정');pin.onclick=async()=>{try{await api('comment/pin',{id:comment.id,pinned:!comment.pinned});await loadEvents()}catch(e){if(e.message!=='취소')toast(e.message)}};actions.append(pin)}if(state.user){const menu=[];if(comment.user_id===state.user.id)menu.push({label:'댓글 수정',run:()=>editComment(comment)});if(comment.user_id===state.user.id||['admin','teacher'].includes(state.user.role))menu.push({label:'댓글 삭제',danger:true,run:async()=>{if(!confirm('댓글을 삭제하시겠어요?'))return;await api('comment/delete',{id:comment.id});await loadEvents()}});if(menu.length){item.tabIndex=0;bindActionMenu(item,'comment-'+comment.id,menu);}}item.append(actions);list.append(item)}}catch(e){if(state.selectedEvent===Number(eventId))list.replaceChildren(elem('p','formMessage',e.message))}}
$('#commentForm').onsubmit=e=>{e.preventDefault();submit(e.target,'#commentMessage',async b=>{await api('comment/save',b);e.target.elements.body.value='';fitTextarea(e.target.elements.body);await loadEvents()})};
$('#expandCalendar').onclick=()=>{state.detail=false;setDetailLayout(false);renderCalendar()};

// 작은 달력: 헤더 드래그 후 네 모서리 중 가장 가까운 곳에 배치합니다.
const miniCalendar=$('.calendarCard'),miniHandle=$('.calendarCard .monthbar');
let miniCorner='bottom-right',miniDrag=null;
miniHandle.tabIndex=0;miniHandle.title='작은 달력 이동: 드래그 또는 방향키';miniHandle.setAttribute('aria-label','달력 상단 · 작은 달력은 드래그 또는 방향키로 위치 이동');
function miniBounds(){const rect=miniCalendar.getBoundingClientRect();return {maxX:Math.max(8,window.innerWidth-rect.width-12),maxY:Math.max(8,window.innerHeight-rect.height-12)}}
function moveMini(x,y){miniCalendar.style.left=x+'px';miniCalendar.style.top=y+'px';miniCalendar.style.right='auto';miniCalendar.style.bottom='auto';}
function dockMini(){if(!state.detail||miniDrag||miniResize)return;miniCalendar.dataset.dock=miniCorner;const b=miniBounds();moveMini(miniCorner.endsWith('right')?b.maxX:12,miniCorner.startsWith('bottom')?b.maxY:12);}
function updateMiniCalendar(detail){if(detail){applyMiniWidth();requestAnimationFrame(dockMini)}else{finishMiniResize(true);finishMiniDrag(true);for(const key of ['left','top','right','bottom'])miniCalendar.style.removeProperty(key)}}
miniHandle.addEventListener('pointerdown',e=>{if(innerWidth<=650||!state.detail||miniResize||e.button!==0||e.target.closest('button'))return;const rect=miniCalendar.getBoundingClientRect();miniDrag={id:e.pointerId,startX:e.clientX,startY:e.clientY,x:rect.left,y:rect.top,moved:false};miniHandle.setPointerCapture(e.pointerId);});
miniHandle.addEventListener('pointermove',e=>{if(!miniDrag||miniDrag.id!==e.pointerId)return;const dx=e.clientX-miniDrag.startX,dy=e.clientY-miniDrag.startY;if(!miniDrag.moved&&Math.hypot(dx,dy)<5)return;miniDrag.moved=true;miniCalendar.classList.add('pipDragging');const b=miniBounds();moveMini(Math.max(8,Math.min(b.maxX,miniDrag.x+dx)),Math.max(8,Math.min(b.maxY,miniDrag.y+dy)));});
function finishMiniDrag(cancel=false){if(!miniDrag)return;const drag=miniDrag;miniDrag=null;if(drag.moved&&!cancel){const rect=miniCalendar.getBoundingClientRect();miniCorner=(rect.top+rect.height/2<window.innerHeight/2?'top':'bottom')+'-'+(rect.left+rect.width/2<window.innerWidth/2?'left':'right');}miniCalendar.classList.remove('pipDragging');if(miniHandle.hasPointerCapture(drag.id))miniHandle.releasePointerCapture(drag.id);dockMini();}
miniHandle.addEventListener('pointerup',()=>finishMiniDrag());miniHandle.addEventListener('pointercancel',()=>finishMiniDrag(true));miniHandle.addEventListener('lostpointercapture',()=>finishMiniDrag(true));
miniHandle.addEventListener('keydown',e=>{if(!state.detail||e.target!==miniHandle)return;let [vertical,horizontal]=miniCorner.split('-');if(e.key==='ArrowLeft')horizontal='left';else if(e.key==='ArrowRight')horizontal='right';else if(e.key==='ArrowUp')vertical='top';else if(e.key==='ArrowDown')vertical='bottom';else return;e.preventDefault();miniCorner=vertical+'-'+horizontal;dockMini();});
window.addEventListener('resize',()=>{finishMiniDrag(true);dockMini()});
const miniSizeObserver=new ResizeObserver(()=>{if(state.detail&&!miniDrag&&!miniResize)requestAnimationFrame(dockMini)});miniSizeObserver.observe(miniCalendar);

let miniWidth=window.innerWidth<=850?260:310,miniHeight=340,miniResize=null;
function miniWidthLimits(){const max=Math.max(1,Math.min(400,window.innerWidth-24));return {min:Math.min(260,max),max};}
function miniHeightLimits(){const max=Math.max(1,Math.min(380,window.innerHeight-24));return {min:Math.min(280,max),max};}
function applyMiniWidth(){const w=miniWidthLimits(),h=miniHeightLimits();miniWidth=Math.min(w.max,Math.max(w.min,miniWidth));miniHeight=Math.min(h.max,Math.max(h.min,miniHeight));miniCalendar.style.setProperty('--mini-width',miniWidth+'px');miniCalendar.style.setProperty('--mini-height',miniHeight+'px');}
function resizeMini(dx,dy){const d=miniResize;if(!d)return;const w=miniWidthLimits(),h=miniHeightLimits();miniWidth=Math.max(w.min,Math.min(w.max,d.width+(d.edge.includes('w')?-dx:d.edge.includes('e')?dx:0)));miniHeight=Math.max(h.min,Math.min(h.max,d.height+(d.edge.includes('n')?-dy:d.edge.includes('s')?dy:0)));
    // 이동 중에는 반대편 변을 고정하고 화면을 벗어나지 않게 합니다.
    if(d.edge.includes('w'))miniWidth=Math.min(miniWidth,d.left+d.width-8);else if(d.edge.includes('e'))miniWidth=Math.min(miniWidth,window.innerWidth-d.left-8);
    if(d.edge.includes('n'))miniHeight=Math.min(miniHeight,d.top+d.height-8);else if(d.edge.includes('s'))miniHeight=Math.min(miniHeight,window.innerHeight-d.top-8);
    applyMiniWidth();moveMini(d.edge.includes('w')?d.left+d.width-miniWidth:d.left,d.edge.includes('n')?d.top+d.height-miniHeight:d.top);
}
function finishMiniResize(cancel=false){if(!miniResize)return;const d=miniResize;miniResize=null;if(cancel){miniWidth=d.width;miniHeight=d.height;}miniCalendar.classList.remove('pipResizing');if(d.handle.hasPointerCapture(d.id))d.handle.releasePointerCapture(d.id);applyMiniWidth();dockMini();}
for(const edge of ['n','s','e','w','ne','nw','se','sw']){const handle=elem('div','miniWindowEdge edge-'+edge);handle.tabIndex=0;handle.setAttribute('role','separator');handle.setAttribute('aria-label',({n:'위',s:'아래',e:'오른쪽',w:'왼쪽',ne:'오른쪽 위',nw:'왼쪽 위',se:'오른쪽 아래',sw:'왼쪽 아래'}[edge])+' 테두리 · 드래그 또는 방향키로 크기 조절');miniCalendar.append(handle);
    handle.addEventListener('pointerdown',e=>{if(!state.detail||e.button!==0||miniDrag||miniResize)return;e.preventDefault();e.stopPropagation();const r=miniCalendar.getBoundingClientRect();miniResize={id:e.pointerId,x:e.clientX,y:e.clientY,width:r.width,height:r.height,left:r.left,top:r.top,edge,handle};miniCalendar.classList.add('pipResizing');handle.setPointerCapture(e.pointerId);});
    handle.addEventListener('pointermove',e=>{if(miniResize?.handle===handle&&miniResize.id===e.pointerId)resizeMini(e.clientX-miniResize.x,e.clientY-miniResize.y)});
    handle.addEventListener('pointerup',()=>{if(miniResize?.handle===handle)finishMiniResize()});handle.addEventListener('pointercancel',()=>{if(miniResize?.handle===handle)finishMiniResize(true)});handle.addEventListener('lostpointercapture',()=>{if(miniResize?.handle===handle)finishMiniResize(true)});
    handle.addEventListener('keydown',e=>{if(!state.detail||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();if(['ArrowLeft','ArrowRight'].includes(e.key)&&/[ew]/.test(edge))miniWidth+=(e.key==='ArrowRight'?10:-10)*(edge.includes('w')?-1:1);if(['ArrowUp','ArrowDown'].includes(e.key)&&/[ns]/.test(edge))miniHeight+=(e.key==='ArrowDown'?10:-10)*(edge.includes('n')?-1:1);applyMiniWidth();dockMini();});
}
window.addEventListener('resize',()=>{finishMiniResize(true);applyMiniWidth();dockMini()});

const actionMenu=elem('div','eventContextMenu');actionMenu.hidden=true;actionMenu.setAttribute('role','menu');actionMenu.setAttribute('aria-label','수정 및 삭제');document.body.append(actionMenu);
let actionMenuKey=null,actionMenuSource=null;
function closeActionMenu(focus=false){actionMenu.hidden=true;actionMenuKey=null;if(focus&&actionMenuSource?.isConnected)actionMenuSource.focus();actionMenuSource=null;}
function bindActionMenu(node,key,actions){node.dataset.actionMenu=key;const more=elem('button','mobileItemMenu','⋯');more.type='button';more.setAttribute('aria-label','수정 및 삭제 메뉴');more.setAttribute('aria-haspopup','menu');more.onclick=event=>{event.stopPropagation();const rect=more.getBoundingClientRect();showActionMenu(node,key,actions,rect.right-160,rect.bottom+4)};node.append(more);node.addEventListener('contextmenu',e=>{if(e.target.closest('[data-action-menu]')!==node)return;if(!actionMenu.hidden&&actionMenuKey===key){closeActionMenu();return}e.preventDefault();showActionMenu(node,key,actions,e.clientX,e.clientY)});node.addEventListener('keydown',e=>{if(e.target!==node||!(e.key==='ContextMenu'||e.shiftKey&&e.key==='F10'))return;e.preventDefault();const r=node.getBoundingClientRect();showActionMenu(node,key,actions,r.left+12,r.top+20)});}
function showActionMenu(source,key,actions,x,y){closeActionMenu();actionMenuKey=key;actionMenuSource=source;actionMenu.replaceChildren();for(const action of actions){const b=elem('button',action.danger?'danger':'',action.label);b.setAttribute('role','menuitem');withActionIcon(b,action.danger?'trash':'edit');b.onclick=async()=>{closeActionMenu();try{await action.run()}catch(e){if(e.message!=='취소')toast(e.message)}};actionMenu.append(b)}actionMenu.hidden=false;actionMenu.style.left=Math.max(8,Math.min(x,innerWidth-actionMenu.offsetWidth-8))+'px';actionMenu.style.top=Math.max(8,Math.min(y,innerHeight-actionMenu.offsetHeight-8))+'px';actionMenu.firstElementChild.focus();}
actionMenu.addEventListener('contextmenu',()=>closeActionMenu());
document.addEventListener('pointerdown',e=>{if(e.button!==2&&!actionMenu.contains(e.target))closeActionMenu()});
document.addEventListener('contextmenu',e=>{if(!e.target.closest('[data-action-menu]')&&!actionMenu.contains(e.target))closeActionMenu()});
document.addEventListener('keydown',e=>{if(actionMenu.hidden)return;if(e.key==='Escape'){e.preventDefault();closeActionMenu(true)}else if(e.key==='Tab')closeActionMenu(true);else if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();const buttons=[...actionMenu.querySelectorAll('button')];let i=buttons.indexOf(document.activeElement);buttons[(i+(e.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length].focus();}});
window.addEventListener('resize',()=>closeActionMenu());window.addEventListener('scroll',()=>closeActionMenu(),true);
function editComment(comment){$('#editCommentForm').reset();$('#editCommentForm').elements.id.value=comment.id;$('#editCommentForm').elements.body.value=comment.body;$('#editCommentMessage').textContent='';$('#editCommentDialog').showModal();requestAnimationFrame(fitAllTextareas)}
$('#editCommentForm').onsubmit=e=>{e.preventDefault();submit(e.target,'#editCommentMessage',async b=>{await api('comment/update',b);$('#editCommentDialog').close();await loadEvents();toast('댓글을 수정했습니다.')})};

function notificationButton(){
    const button=elem('button','notificationButton');button.type='button';
    const count=Number(state.unread)||0;
    const label=count?'알림함 · 읽지 않은 알림 '+count+'개':'알림함 · 읽지 않은 알림 없음';
    button.setAttribute('aria-label',label);button.title=label;button.setAttribute('aria-haspopup','dialog');
    const ns='http://www.w3.org/2000/svg';const svg=document.createElementNS(ns,'svg');
    svg.setAttribute('viewBox','0 0 24 24');svg.setAttribute('width','22');svg.setAttribute('height','22');svg.setAttribute('fill','none');svg.setAttribute('stroke','currentColor');svg.setAttribute('stroke-width','1.7');svg.setAttribute('stroke-linecap','round');svg.setAttribute('stroke-linejoin','round');svg.setAttribute('aria-hidden','true');svg.setAttribute('focusable','false');
    const path=document.createElementNS(ns,'path');path.setAttribute('d','M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4');svg.append(path);button.append(svg);
    if(count){const badge=elem('span','notificationBadge',count>99?'99+':String(count));badge.setAttribute('aria-hidden','true');button.append(badge)}
    return button;
}


let mealRequest=0,mealMonth=new Date(new Date().getFullYear(),new Date().getMonth(),1),mealSelected=dateKey(new Date()),mealDays={},mealLoaded=false;
async function loadMeal(){const request=++mealRequest;const month=dateKey(mealMonth).slice(0,7);mealLoaded=false;mealDays={};$('#mealStatus').textContent='급식을 불러오는 중입니다.';renderMealCalendar();try{const data=await api('meals?month='+month);if(request!==mealRequest)return;mealDays=data.days;mealLoaded=true;$('#mealStatus').textContent=Object.keys(mealDays).length?'날짜를 선택하면 오른쪽에서 상세 메뉴를 확인할 수 있어요.':'이번 달에 등록된 급식 정보가 없습니다.';renderMealCalendar()}catch(error){if(request!==mealRequest)return;$('#mealStatus').textContent=error.message;$('#mealContent').replaceChildren(elem('p','formMessage',error.message));const retry=elem('button','secondary','다시 시도');retry.onclick=loadMeal;$('#mealContent').append(retry)}}
function renderMealCalendar(){const y=mealMonth.getFullYear(),m=mealMonth.getMonth();$('#mealMonthTitle').textContent=y+'년 '+(m+1)+'월';const start=new Date(y,m,1);start.setDate(1-start.getDay());const count=Math.ceil((new Date(y,m,1).getDay()+new Date(y,m+1,0).getDate())/7)*7;const grid=$('#mealCalendar');grid.replaceChildren();for(let i=0;i<count;i++){const day=new Date(start);day.setDate(start.getDate()+i);const key=dateKey(day);const outside=day.getMonth()!==m;const b=elem('button','mealDay'+(outside?' outside':'')+(key===mealSelected?' chosen':'')+(key===dateKey(new Date())?' isToday':''));b.setAttribute('aria-label',key+' 급식 보기');b.setAttribute('aria-pressed',key===mealSelected);b.append(elem('span','dateNumber',day.getDate()));if(!outside){const meals=mealDays[key]||[];for(const meal of meals){b.append(elem('span','mealLabel',meal.name));for(const dish of meal.dishes)b.append(elem('span','mealDish',dish))}if(mealLoaded&&!meals.length)b.append(elem('span','mealNone','등록된 급식 없음'))}b.onclick=()=>{mealSelected=key;if(outside){mealMonth=new Date(day.getFullYear(),day.getMonth(),1);loadMeal()}else renderMealCalendar();scrollToMealDetails()};grid.append(b)}renderMealDetails()}
function renderMealDetails(){const content=$('#mealContent');content.replaceChildren();const title=elem('h3','',new Date(mealSelected+'T12:00:00').toLocaleDateString('ko-KR',{month:'long',day:'numeric',weekday:'long'}));content.append(title);if(!mealLoaded){content.append(elem('p','muted','급식을 불러오는 중입니다.'));return}const meals=mealDays[mealSelected]||[];if(!meals.length){content.append(elem('div','mealEmpty','해당 날짜에 등록된 급식 정보가 없습니다.'));return}for(const meal of meals){const card=elem('article','mealCard');card.append(elem('span','tag',meal.name));const list=elem('ul','dishList');meal.dishes.forEach(dish=>list.append(elem('li','',dish)));card.append(list);if(meal.calories)card.append(elem('p','mealCalories',meal.calories));for(const [title,values] of [['영양 정보',meal.nutrition],['원산지 정보',meal.origins]])if(values.length){const details=elem('details','mealDetails');details.append(elem('summary','',title),elem('p','',values.join('\n')));card.append(details)}content.append(card)}}
$('#mealNav').onclick=()=>{closeMobileQuickMenu();$('.workspace').hidden=true;$('.toolbar').hidden=true;$('#adminPage').hidden=true;$('#mealPage').hidden=false;for(const id of ['#allNav','#schoolNav','#classNav','#adminNav'])$(id).classList.remove('active');$('#mealNav').classList.add('active');$('#viewLabel').textContent='급식';loadMeal()};
function moveMealMonth(offset){mealMonth=new Date(mealMonth.getFullYear(),mealMonth.getMonth()+offset,1);mealSelected=dateKey(mealMonth);loadMeal()}
$('#mealPrev').onclick=()=>moveMealMonth(-1);$('#mealNext').onclick=()=>moveMealMonth(1);$('#mealToday').onclick=()=>{const today=new Date();mealMonth=new Date(today.getFullYear(),today.getMonth(),1);mealSelected=dateKey(today);loadMeal()};

function scrollToMealDetails(){
    const target=window.matchMedia('(max-width:1150px)').matches?$('#mealContent'):$('.mealLayout');
    const rect=target.getBoundingClientRect();
    if(rect.top<20||rect.top>window.innerHeight*0.35){
        window.scrollTo({top:Math.max(0,window.scrollY+rect.top-24),behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});
    }
}

function scrollToScheduleDetails(){
    if(!state.events.some(event=>event.date===state.selected))return;
    const narrow=window.matchMedia(state.detail?'(max-width:850px)':'(max-width:1050px)').matches;
    const target=narrow?(state.detail?$('#commentsPanel'):$('.agenda')):$('.workspace');
    const rect=target.getBoundingClientRect();
    if(rect.top<20||rect.top>window.innerHeight*0.35){
        window.scrollTo({top:Math.max(0,window.scrollY+rect.top-24),behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});
    }
}

let mobileMiniExpanded=false;
const mobileMiniToggle=elem('button','mobileMiniToggle');mobileMiniToggle.type='button';document.body.append(mobileMiniToggle);
function syncMobileMini(detail){mobileMiniExpanded=false;const mobile=innerWidth<=650;miniCalendar.classList.toggle('mobileMiniCollapsed',mobile&&detail);if(!mobile||!detail)closeMobileQuickMenu();mobileMiniToggle.setAttribute('aria-expanded',String(!mobileQuickMenu.hidden));mobileMiniToggle.setAttribute('aria-controls','mobileQuickMenu');mobileMiniToggle.setAttribute('aria-haspopup','menu');mobileMiniToggle.setAttribute('aria-label','화면 이동 메뉴');mobileMiniToggle.title='화면 이동 메뉴';mobileMiniToggle.replaceChildren(makeMobileMenuIcon());}
mobileMiniToggle.onclick=e=>{e.stopPropagation();if(!mobileQuickMenu.hidden){closeMobileQuickMenu();return}mobileQuickMenu.hidden=false;mobileMiniToggle.setAttribute('aria-expanded','true');mobileQuickMenu.querySelector('button').focus()};
window.addEventListener('resize',()=>syncMobileMini(state.detail));

function makeMobileCalendarIcon(expanded){const ns='http://www.w3.org/2000/svg';const svg=document.createElementNS(ns,'svg');for(const [key,value] of Object.entries({viewBox:'0 0 24 24',width:'22',height:'22',fill:'none',stroke:'currentColor','stroke-width':'1.7','stroke-linecap':'round','stroke-linejoin':'round','aria-hidden':'true',focusable:'false'}))svg.setAttribute(key,value);const path=document.createElementNS(ns,'path');path.setAttribute('d',expanded?'M5 3h14a2 2 0 0 1 2 2v15H3V5a2 2 0 0 1 2-2ZM7 1v4m10-4v4M3 8h18m-12 7 3-3 3 3':'M5 3h14a2 2 0 0 1 2 2v15H3V5a2 2 0 0 1 2-2ZM7 1v4m10-4v4M3 8h18m-12 5 3 3 3-3');svg.append(path);return svg;}

const mobileQuickMenu=elem('div','mobileQuickMenu');mobileQuickMenu.id='mobileQuickMenu';mobileQuickMenu.hidden=true;mobileQuickMenu.setAttribute('role','menu');mobileQuickMenu.setAttribute('aria-label','화면 이동');document.body.append(mobileQuickMenu);
function closeMobileQuickMenu(focus=false){mobileQuickMenu.hidden=true;mobileMiniToggle.setAttribute('aria-expanded','false');if(focus)mobileMiniToggle.focus();}
for(const [label,scope] of [['전체 일정','all'],['학사일정','school'],['학급일정','class'],['급식','meals'],['관리자 문의','inquiry'],['관리자','admin']]){const b=elem('button','',label);b.setAttribute('role','menuitem');if(scope==='inquiry'){b.textContent='';b.dataset.inquiryMenu='true';b.append(elem('span','quickInquiryLabel',state.user?.role==='admin'?'문의함':'관리자 문의'))}if(scope==='admin'){b.dataset.adminMenu='true';b.hidden=state.user?.role!=='admin'}withActionIcon(b,scope==='admin'?'settings':scope==='inquiry'?'mail':scope==='meals'?'meal':scope==='class'?'class':'calendar');b.onclick=async()=>{closeMobileQuickMenu();if(scope==='admin'){$('#adminNav').click();return}if(scope==='inquiry'){$('#inquiryNav').click();return}if(scope==='meals'){$('#mealNav').click();return}state.detail=false;setDetailLayout(false);await setScope(scope);$('.calendarCard .monthbar').focus();window.scrollTo({top:Math.max(0,scrollY+$('.workspace').getBoundingClientRect().top-24),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})};mobileQuickMenu.append(b);}
document.addEventListener('pointerdown',e=>{if(!mobileQuickMenu.contains(e.target)&&!mobileMiniToggle.contains(e.target))closeMobileQuickMenu()});
document.addEventListener('keydown',e=>{if(mobileQuickMenu.hidden)return;if(e.key==='Escape'){e.preventDefault();closeMobileQuickMenu(true)}else if(['ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();const buttons=[...mobileQuickMenu.querySelectorAll('button')],i=buttons.indexOf(document.activeElement);buttons[(i+(e.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length].focus()}else if(e.key==='Tab')closeMobileQuickMenu(true)});
function makeMobileMenuIcon(){const ns='http://www.w3.org/2000/svg';const svg=document.createElementNS(ns,'svg');for(const [key,value] of Object.entries({viewBox:'0 0 24 24',width:'22',height:'22',fill:'none',stroke:'currentColor','stroke-width':'1.7','aria-hidden':'true',focusable:'false'}))svg.setAttribute(key,value);for(const [x,y] of [[3,3],[14,3],[3,14],[14,14]]){const rect=document.createElementNS(ns,'rect');for(const [key,value] of Object.entries({x,y,width:7,height:7,rx:1.5}))rect.setAttribute(key,value);svg.append(rect)}return svg;}

function withActionIcon(button,name){
    if(!button||button.querySelector('.actionIcon'))return;
    const paths={
        calendar:'M4 4h16v17H4zM8 2v4m8-4v4M4 9h16m-12 4h2m4 0h2m-8 4h2',
        class:'M3 4h18v13H3zM8 21l4-4 4 4M7 8h10m-10 4h6',
        meal:'M4 3v5a3 3 0 0 0 6 0V3M7 3v18M19 3c-3 3-4 7-1 9h2V3h-1Zm1 9v9',
        user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM4 21v-2a8 8 0 0 1 16 0v2',
        login:'M14 3h6v18h-6M3 12h12m-4-4 4 4-4 4',
        logout:'M10 3H4v18h6m3-13 4 4-4 4m-4-4h12',
        edit:'m15 4 5 5M4 20l5-1L21 7l-5-5L4 14v6Z',
        trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7',
        add:'M12 4v16M4 12h16',
        mail:'M3 5h18v14H3zM3 5l9 7 9-7',
        settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2',
        save:'M4 3h13l4 4v14H3V3h1Zm3 0v6h10V3M7 21v-8h10v8'
    };
    const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');
    for(const [key,value] of Object.entries({viewBox:'0 0 24 24',width:'18',height:'18',fill:'none',stroke:'currentColor','stroke-width':'1.6','stroke-linecap':'round','stroke-linejoin':'round','aria-hidden':'true',focusable:'false',class:'actionIcon'}))svg.setAttribute(key,value);
    const path=document.createElementNS(ns,'path');path.setAttribute('d',paths[name]||paths.calendar);svg.append(path);button.prepend(svg);
}
for(const [id,icon] of [['allNav','calendar'],['schoolNav','calendar'],['classNav','class'],['adminNav','settings'],['mealNav','meal'],['inquiryNav','mail']]){const button=$('#'+id);for(const node of [...button.childNodes])if(node.nodeType===Node.TEXT_NODE)node.remove();withActionIcon(button,icon)}
for(const [id,icon] of [['addEvent','add'],['adminAddEvent','add'],['loadUsers','user'],['loadInquiries','mail'],['sendCode','mail'],['userSendCode','mail']]){const button=$('#'+id);if(id==='addEvent')button.textContent='일정 등록';withActionIcon(button,icon)}
for(const id of ['eventForm','userForm','editCommentForm','passwordForm'])withActionIcon($('#'+id+' button[type="submit"]')||$('#'+id+' .primary'),'save');
for(const id of ['commentForm','inquiryForm','replyForm','noticeForm'])withActionIcon($('#'+id+' .primary'),'mail');

