async function logoutAccount(){try{await api('logout',{});if($('#profileDialog').open)$('#profileDialog').close();if($('#passwordDialog').open)$('#passwordDialog').close();closeMobileQuickMenu();await bootstrap();toast('로그아웃했습니다.')}catch(error){toast(error.message)}}
$('#profileLogout').onclick=logoutAccount;

withActionIcon($('#profileLogout'),'logout');

let usernameCheckTimer;
function resetSignupValidation(){clearTimeout(usernameCheckTimer);for(const name of ['username','password_confirm'])$('#authForm').elements[name].setCustomValidity('');for(const id of ['usernameStatus','signupPasswordStatus']){$('#'+id).textContent='';$('#'+id).hidden=state.auth!=='register'}$('#forgotPassword').hidden=state.auth!=='login';}
async function checkUsername(){if(state.auth!=='register')return;const field=$('#authForm').elements.username,value=field.value.trim().toLowerCase(),status=$('#usernameStatus');field.setCustomValidity('');status.className='fieldStatus';if(!value){status.textContent='';return}if(!/^[a-z0-9_]{4,30}$/.test(value)){status.textContent='영문·숫자·밑줄 4~30자로 입력하세요.';field.setCustomValidity(status.textContent);return}status.textContent='사용 가능 여부를 확인하고 있습니다…';try{const result=await api('username-check',{username:value});if(state.auth!=='register'||field.value.trim().toLowerCase()!==value)return;status.textContent=result.available?'사용 가능한 아이디입니다.':'이미 사용 중인 아이디입니다.';status.classList.toggle('success',result.available);field.setCustomValidity(result.available?'':'이미 사용 중인 아이디입니다.')}catch(error){if(field.value.trim().toLowerCase()===value)status.textContent=error.message}}
$('#authForm').elements.username.addEventListener('input',()=>{$('#authForm').elements.username.setCustomValidity('');$('#usernameStatus').textContent='';clearTimeout(usernameCheckTimer);if(state.auth==='register')usernameCheckTimer=setTimeout(checkUsername,450)});
$('#authForm').elements.username.addEventListener('blur',()=>{clearTimeout(usernameCheckTimer);checkUsername()});
function checkSignupPasswords(){const f=$('#authForm'),status=$('#signupPasswordStatus');f.elements.password_confirm.setCustomValidity('');if(state.auth!=='register')return;const password=f.elements.password.value,confirmation=f.elements.password_confirm.value;status.className='fieldStatus';if(!confirmation){status.textContent='';return}const match=password===confirmation;status.textContent=match?'비밀번호가 일치합니다.':'비밀번호가 일치하지 않습니다.';status.classList.toggle('success',match);f.elements.password_confirm.setCustomValidity(match?'':'비밀번호 확인이 일치하지 않습니다.');}
for(const name of ['password','password_confirm'])$('#authForm').elements[name].addEventListener('input',checkSignupPasswords);
$('#forgotPassword').onclick=()=>{$('#recoveryForm').reset();$('#recoveryMessage').textContent='';$('#authDialog').close();$('#recoveryDialog').showModal()};
$('#requestRecovery').onclick=async()=>{const f=$('#recoveryForm'),button=$('#requestRecovery');if(!f.elements.username.reportValidity()||!f.elements.email.reportValidity())return;button.disabled=true;$('#recoveryMessage').textContent='요청 중입니다…';try{const result=await api('password/request',{username:f.elements.username.value,email:f.elements.email.value});$('#recoveryMessage').textContent=result.message}catch(error){$('#recoveryMessage').textContent=error.message}finally{button.disabled=false}};
$('#recoveryForm').onsubmit=e=>{e.preventDefault();submit(e.target,'#recoveryMessage',async b=>{if(b.new_password!==b.password_confirm)throw Error('새 비밀번호 확인이 일치하지 않습니다.');await api('password/reset',b);$('#recoveryDialog').close();await bootstrap();openAuth('login');$('#authMessage').textContent='비밀번호를 변경했습니다. 새 비밀번호로 로그인해 주세요.'})};
withActionIcon($('#requestRecovery'),'mail');withActionIcon($('#recoveryForm .primary'),'save');

function notificationResult(result){return '사이트 알림 '+result.recipients+'명 전달 · 이메일 '+result.email_sent+'건 SMTP 접수'+(result.email_failed?' · '+result.email_failed+'건 실패 (SMTP 설정·발송 제한을 확인하세요.)':'');}
$('#loadNoticeRecipients').onclick=()=>loadRecipientDirectory(1);
withActionIcon($('#loadNoticeRecipients'),'user');

const selectedRecipients=new Map();let recipientPageUsers=[];
function ensureDirectoryFilters(id){const select=$('#'+id);if(select.options.length)return;for(const [value,label] of [['','전체 학급'],...[...state.classes,'교사','관리자'].map(c=>[c,c])]){const option=elem('option','',label);option.value=value;select.append(option)}}
function directoryPager(id,data,load){const area=$('#'+id);area.replaceChildren(elem('span','',data.total+'명 · '+data.page+' / '+data.pages+'페이지'));for(const [label,page,disabled] of [['이전',data.page-1,data.page<=1],['다음',data.page+1,data.page>=data.pages]]){const b=elem('button','secondary',label);b.type='button';b.disabled=disabled;b.onclick=()=>load(page);area.append(b)}}
function editMember(user){const form=$('#userForm');form.reset();$('#userMessage').textContent='';for(const [key,value] of Object.entries(user))if(form.elements[key])form.elements[key].value=value;$('#userDialog').showModal()}
async function loadMemberDirectory(page){try{ensureDirectoryFilters('memberClass');const result=await api('admin/users',{q:$('#memberSearch').value,class_name:$('#memberClass').value,page});$('#memberSearchPanel').hidden=false;const list=$('#userList');list.replaceChildren();for(const user of result.users){const row=elem('div','userRow');const text=elem('div','',user.name+' · '+user.username);text.append(elem('small','',user.class_name+' · '+user.email));const edit=elem('button','secondary','수정');withActionIcon(edit,'edit');edit.onclick=()=>editMember(user);row.append(text,edit);list.append(row)}if(!result.users.length)list.append(elem('p','muted','검색 결과가 없습니다.'));directoryPager('memberPagination',result,loadMemberDirectory)}catch(error){if(error.message!=='취소')toast(error.message)}}
async function loadRecipientDirectory(page){try{ensureDirectoryFilters('recipientClass');const result=await api('admin/users',{q:$('#recipientSearch').value,class_name:$('#recipientClass').value,page});recipientPageUsers=result.users;renderRecipientResults();directoryPager('recipientPagination',result,loadRecipientDirectory)}catch(error){if(error.message!=='취소')toast(error.message)}}
function renderRecipientResults(){const list=$('#recipientResults');list.replaceChildren();for(const user of recipientPageUsers){const row=elem('label','recipientRow'),check=elem('input');check.type='checkbox';check.checked=selectedRecipients.has(user.id);check.onchange=()=>{if(check.checked)selectedRecipients.set(user.id,user);else selectedRecipients.delete(user.id);renderSelectedRecipients()};const text=elem('span','',user.name+' · '+user.username);text.append(elem('small','',user.class_name+' · '+user.email));row.append(check,text);list.append(row)}if(!recipientPageUsers.length)list.append(elem('p','muted','검색 결과가 없습니다.'));renderSelectedRecipients()}
function renderSelectedRecipients(){$('#selectedRecipientCount').textContent='선택 '+selectedRecipients.size+'명';const area=$('#selectedRecipientList');area.replaceChildren();for(const user of [...selectedRecipients.values()].slice(0,30)){const b=elem('button','recipientChip',user.name+' · '+user.username+' ×');b.type='button';b.setAttribute('aria-label',user.name+' 수신자 선택 해제');b.onclick=()=>{selectedRecipients.delete(user.id);renderRecipientResults()};area.append(b)}if(selectedRecipients.size>30)area.append(elem('span','hint','외 '+(selectedRecipients.size-30)+'명'))}
$('#selectRecipientPage').onclick=()=>{recipientPageUsers.forEach(user=>selectedRecipients.set(user.id,user));renderRecipientResults()};$('#clearRecipients').onclick=()=>{selectedRecipients.clear();renderRecipientResults()};
$('#noticeMode').onchange=()=>{$('#recipientPicker').hidden=$('#noticeMode').value==='all'};
$('#memberSearchButton').onclick=()=>loadMemberDirectory(1);$('#recipientSearchButton').onclick=()=>loadRecipientDirectory(1);
for(const [id,load] of [['memberSearch',loadMemberDirectory],['recipientSearch',loadRecipientDirectory]])$('#'+id).addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();load(1)}});

function clearDirectoryState(){adminInquiries=[];$('#inquiryList').replaceChildren();$('#inquiryStatus').textContent='';$('#emailHistory').replaceChildren();selectedRecipients.clear();recipientPageUsers=[];for(const id of ['recipientResults','recipientPagination','selectedRecipientList','userList','memberPagination'])$('#'+id).replaceChildren();$('#memberSearchPanel').hidden=true;$('#selectedRecipientCount').textContent='선택 0명';}

$('#loadEmailHistory').onclick=async()=>{try{const result=await api('admin/email-history',{});const list=$('#emailHistory');list.replaceChildren();for(const note of result.deliveries){const row=elem('article','messageCard');row.append(elem('strong','',note.name+' · '+note.title),elem('small','',note.email+' · '+({sent:'SMTP 접수 완료',failed:'전송 실패',not_sent:'발송 시도 없음',pending:'발송 대기'}[note.email_status]||note.email_status)));if(note.email_error)row.append(elem('p','formMessage',note.email_error));if(note.email_status!=='sent'){const retry=elem('button','secondary',note.email_status==='not_sent'?'이메일 보내기':'이메일 재시도');retry.type='button';withActionIcon(retry,'mail');retry.onclick=async()=>{retry.disabled=true;try{const result=await api('admin/email-retry',{id:note.id});toast(result.email_status==='sent'?'SMTP 서버가 이메일을 접수했습니다.':result.error);list.replaceChildren(elem('p','muted','결과가 저장되었습니다. 발송 내역을 다시 조회해 주세요.'))}catch(error){if(error.message!=='취소')toast(error.message)}finally{retry.disabled=false}};row.append(retry)}list.append(row)}if(!result.deliveries.length)list.append(elem('p','muted','발송 내역이 없습니다.'))}catch(error){if(error.message!=='취소')toast(error.message)}};
withActionIcon($('#loadEmailHistory'),'mail');

let adminInquiries=[];
function selectAdminPane(name,load=false){document.querySelectorAll('[data-admin-pane]').forEach(panel=>panel.hidden=panel.dataset.adminPane!==name);document.querySelectorAll('[data-admin-tab]').forEach(button=>{const active=button.dataset.adminTab===name;button.classList.toggle('selected',active);button.setAttribute('aria-selected',String(active))});if(name==='inquiries'&&load)loadAdminInquiries();}
document.querySelectorAll('[data-admin-tab]').forEach(button=>{withActionIcon(button,{inquiries:'mail',members:'user',schedule:'calendar',notices:'mail',delivery:'mail',settings:'settings'}[button.dataset.adminTab]);button.onclick=()=>selectAdminPane(button.dataset.adminTab,button.dataset.adminTab==='inquiries')});
async function loadAdminInquiries(){const button=$('#loadInquiries');button.disabled=true;$('#inquiryStatus').textContent='문의를 확인하고 있습니다…';try{const result=await api('admin/inquiries',{});adminInquiries=result.inquiries;renderAdminInquiries()}catch(error){$('#inquiryStatus').textContent=error.message==='취소'?'문의를 확인하려면 문의 새로고침을 눌러 주세요.':error.message}finally{button.disabled=false}}
function renderAdminInquiries(){const q=$('#inquirySearch').value.trim().toLowerCase(),filter=$('#inquiryStatusFilter').value;const items=adminInquiries.filter(item=>(filter==='all'||(filter==='answered'?!!item.reply:!item.reply))&&[item.title,item.body,item.name,item.email].some(value=>(value||'').toLowerCase().includes(q)));$('#inquiryStatus').textContent='전체 '+adminInquiries.length+'건 · 미답변 '+adminInquiries.filter(item=>!item.reply).length+'건 · 현재 '+items.length+'건';const list=$('#inquiryList');list.replaceChildren();if(!items.length)list.append(elem('p','muted','표시할 문의가 없습니다.'));for(const inquiry of items){const card=elem('article','messageCard');card.append(elem('span','tag',inquiry.reply?'답변 완료':'미답변'),elem('h3','',inquiry.title),elem('small','',(inquiry.name||'삭제된 회원')+' · '+(inquiry.class_name||'')+' · '+new Date(inquiry.created).toLocaleString('ko-KR')),elem('p','',inquiry.body));appendInquiryImages(card,inquiry.images);if(inquiry.reply)card.append(elem('p','replyText','답변: '+inquiry.reply));const reply=elem('button','secondary',inquiry.reply?'추가 회신':'회신');withActionIcon(reply,'mail');reply.onclick=()=>{$('#replyForm').reset();$('#replyForm').elements.id.value=inquiry.id;$('#replyTitle').textContent=inquiry.title;$('#replyOriginal').replaceChildren(elem('strong','',inquiry.name||'삭제된 회원'),elem('p','',inquiry.body));appendInquiryImages($('#replyOriginal'),inquiry.images);$('#replyMessage').textContent='';$('#replyDialog').showModal()};card.append(reply);list.append(card)}}
$('#inquirySearch').oninput=renderAdminInquiries;$('#inquiryStatusFilter').onchange=renderAdminInquiries;
$('#loadInquiries').textContent='문의 새로고침';withActionIcon($('#loadInquiries'),'mail');

let inquiryImageFiles=[];
function clearInquiryImages(){for(const image of inquiryImageFiles)URL.revokeObjectURL(image.url);inquiryImageFiles=[];$('#inquiryImagePreviews').replaceChildren();$('#inquiryImageFiles').value='';}
function addInquiryImages(files){const allowed=['image/png','image/jpeg','image/gif','image/webp'];for(const file of files){if(!allowed.includes(file.type)){$('#inquiryMessage').textContent='PNG, JPEG, GIF, WebP 이미지만 첨부할 수 있습니다.';continue}if(file.size>2*1024*1024){$('#inquiryMessage').textContent='이미지는 한 장당 2MB 이하여야 합니다.';continue}if(inquiryImageFiles.length>=3){$('#inquiryMessage').textContent='이미지는 최대 3장까지 첨부할 수 있습니다.';break}inquiryImageFiles.push({file,url:URL.createObjectURL(file)})}renderInquiryImagePreviews();}
function renderInquiryImagePreviews(){const list=$('#inquiryImagePreviews');list.replaceChildren();inquiryImageFiles.forEach((image,index)=>{const item=elem('div','imagePreview');const preview=elem('img');preview.src=image.url;preview.alt='첨부 이미지 '+(index+1);const remove=elem('button','imageRemove','×');remove.type='button';remove.setAttribute('aria-label','첨부 이미지 '+(index+1)+' 삭제');remove.onclick=()=>{URL.revokeObjectURL(image.url);inquiryImageFiles.splice(index,1);renderInquiryImagePreviews()};item.append(preview,remove);list.append(item)})}
$('#inquiryImageFiles').onchange=e=>{addInquiryImages(e.target.files);e.target.value=''};
$('#inquiryDialog').addEventListener('paste',e=>{if(e.target.closest('input[type=password]'))return;const files=[...(e.clipboardData?.items||[])].filter(item=>item.kind==='file'&&item.type.startsWith('image/')).map(item=>item.getAsFile()).filter(Boolean);if(files.length){e.preventDefault();addInquiryImages(files)}});
$('#inquiryForm').addEventListener('reset',clearInquiryImages);
async function encodeInquiryImages(){return Promise.all(inquiryImageFiles.map(image=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve({data:String(reader.result).split(',')[1]});reader.onerror=()=>reject(Error('이미지를 읽지 못했습니다. 다시 첨부해 주세요.'));reader.readAsDataURL(image.file)})))}
function appendInquiryImages(container,images){if(!images?.length)return;const gallery=elem('div','inquiryImages');for(const image of images){const link=elem('a','inquiryImageLink');link.href='/api/inquiry-image?id='+encodeURIComponent(image.id);link.target='_blank';link.rel='noopener';link.setAttribute('aria-label',image.name+' 원본 보기');const img=elem('img');img.src=link.href;img.alt=image.name;img.loading='lazy';link.append(img);gallery.append(link)}container.append(gallery)}

// 알림함 바깥 배경에서 클릭을 시작하고 끝낸 경우에만 닫습니다.
let notificationBackdropPress=false;
const notificationDialog=$('#notificationsDialog');
function outsideNotificationDialog(event){const rect=notificationDialog.getBoundingClientRect();return event.target===notificationDialog&&(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom);}
notificationDialog.addEventListener('pointerdown',event=>{notificationBackdropPress=event.button===0&&outsideNotificationDialog(event)});
notificationDialog.addEventListener('click',event=>{if(notificationBackdropPress&&outsideNotificationDialog(event))notificationDialog.close();notificationBackdropPress=false;});
notificationDialog.addEventListener('pointercancel',()=>{notificationBackdropPress=false});
notificationDialog.addEventListener('close',()=>{notificationBackdropPress=false});

const profileDialog=$('#profileDialog');
let profileBackdropPress=false;
function outsideProfileDialog(event){const rect=profileDialog.getBoundingClientRect();return event.target===profileDialog&&(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom);}
profileDialog.addEventListener('pointerdown',event=>{profileBackdropPress=event.button===0&&outsideProfileDialog(event)});
profileDialog.addEventListener('click',event=>{if(profileBackdropPress&&outsideProfileDialog(event))profileDialog.close();profileBackdropPress=false;});
profileDialog.addEventListener('pointercancel',()=>{profileBackdropPress=false});
profileDialog.addEventListener('close',()=>{profileBackdropPress=false});
